package local.castle.tv;

import android.content.*;
import android.content.pm.PackageManager;
import android.database.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import java.util.*;
import java.util.concurrent.*;
import java.io.*;
import java.net.*;

/** Read-only Android TV Watch Next / preview channels. Never invents or edits provider rows. */
final class TvShelf {
  static final String PERMISSION="android.permission.READ_TV_LISTINGS";
  static final Uri NEXT=Uri.parse("content://android.media.tv/watch_next_program"),PREVIEW=Uri.parse("content://android.media.tv/preview_program"),CHANNEL=Uri.parse("content://android.media.tv/channel");
  static final class Item {long id,position,duration,engaged,type;String title,pkg,intent,poster,source;boolean recent;}
  final Context context;final Handler main=new Handler(Looper.getMainLooper());final Runnable changed;final ExecutorService worker=Executors.newSingleThreadExecutor(),artWorker=Executors.newSingleThreadExecutor();
  List<Item> next=Collections.emptyList(),picks=Collections.emptyList();boolean loading,loaded,denied,failed,registered,closed,refreshAgain,resetPending;long lastLoad;
  final LinkedHashMap<String,Bitmap> images=new LinkedHashMap<>();final HashSet<String> pending=new HashSet<>(),failedImages=new HashSet<>();
  final Runnable periodic=new Runnable(){public void run(){if(!registered||closed)return;forceSources();main.postDelayed(this,1800000);}};
  final Runnable reload=new Runnable(){public void run(){refresh(true);}};
  final ContentObserver observer=new ContentObserver(main){public void onChange(boolean self,Uri uri){main.removeCallbacks(reload);main.postDelayed(reload,1000);}};
  final SharedPreferences prefs;final HashSet<String> hidden=new HashSet<>();int artGeneration;List<Item> rawNext=Collections.emptyList(),rawPicks=Collections.emptyList();
  TvShelf(Context c,Runnable r){context=c;changed=r;prefs=c.getSharedPreferences("castle-shelf",0);hidden.addAll(prefs.getStringSet("hidden",Collections.<String>emptySet()));}
  String fingerprint(Item i){return TvCardPolicy.fingerprint(i.pkg+"\n"+i.id+"\n"+i.intent+"\n"+i.position+"/"+i.duration+"/"+i.engaged+"/"+i.type+"\n"+i.title+"\n"+i.poster);}
  List<Item> visible(List<Item> rows){ArrayList<Item> result=new ArrayList<>();for(Item i:rows)if(!hidden.contains(fingerprint(i)))result.add(i);return Collections.unmodifiableList(result);}
  void clearArtwork(){artGeneration++;images.clear();pending.clear();failedImages.clear();}
  void resetOldCards(){context.getSharedPreferences("castle-live",0).edit().remove("rows").apply();resetPending=true;for(Item i:rawNext)hidden.add(fingerprint(i));for(Item i:rawPicks)hidden.add(fingerprint(i));persistHidden();next=Collections.emptyList();picks=Collections.emptyList();clearArtwork();changed.run();refresh(true);}
  void reconnect(){resetPending=false;hidden.clear();persistHidden();clearArtwork();next=visible(rawNext);picks=visible(rawPicks);changed.run();refresh(true);}
  void persistHidden(){prefs.edit().putStringSet("hidden",new HashSet<>(hidden)).apply();}

  final SourceRefresh sourceSync=new SourceRefresh();String syncMessage="";int requestedSources;
  String publication(){StringBuilder s=new StringBuilder();for(Item i:rawNext)s.append(fingerprint(i));for(Item i:rawPicks)s.append(fingerprint(i));return TvCardPolicy.fingerprint(s.toString());}
  boolean syncReceiver(String pkg,String name){try{ComponentName n=new ComponentName(pkg,name);android.content.pm.ActivityInfo info=context.getPackageManager().getReceiverInfo(n,0);if(!info.enabled||!info.exported)return false;context.sendBroadcast(new Intent("android.media.tv.action.INITIALIZE_PROGRAMS").setComponent(n).addFlags(Intent.FLAG_INCLUDE_STOPPED_PACKAGES));return true;}catch(Exception e){android.util.Log.w("CastleShelf","Source request unavailable: "+pkg+" "+e.getClass().getSimpleName());return false;}}
  void forceSources(){if(closed||sourceSync.active)return;sourceSync.begin(SystemClock.uptimeMillis(),publication());syncMessage="Запрашиваем свежие данные приложений…";requestedSources=0;if(syncReceiver("org.smarttube.stable","com.liskovsoft.leanbackassistant.channels.UpdateChannelsReceiver"))requestedSources++;if(syncReceiver("org.smarttube.beta","com.liskovsoft.leanbackassistant.channels.UpdateChannelsReceiver"))requestedSources++;if(syncReceiver("com.google.android.youtube.tv","com.google.android.libraries.youtube.tv.recommendations.RecommendationsScheduler$Receiver"))requestedSources++;clearArtwork();refresh(true);main.removeCallbacks(sourcePoll);main.postDelayed(sourcePoll,1000);changed.run();}
  final Runnable sourcePoll=new Runnable(){public void run(){if(closed||!sourceSync.active)return;long now=SystemClock.uptimeMillis();if(sourceSync.done(now)||requestedSources==0){sourceSync.finish();syncMessage=requestedSources==0?"Приложения не приняли запрос обновления":sourceSync.changed?"Получены обновлённые ТВ-карточки":"Приложения не прислали новых карточек";android.util.Log.i("CastleShelf","Source refresh finished changed="+sourceSync.changed+" requested="+requestedSources);changed.run();return;}refresh(true);main.postDelayed(this,2000);}};
  boolean allowed(){return context.checkSelfPermission(PERMISSION)==PackageManager.PERMISSION_GRANTED;}
  void start(){sourceSync.resume(SystemClock.uptimeMillis());if(sourceSync.active){android.util.Log.i("CastleShelf","Source polling resumed");main.removeCallbacks(sourcePoll);main.postDelayed(sourcePoll,1000);}if(!registered&&allowed()){try{for(Uri u:new Uri[]{NEXT,PREVIEW,CHANNEL})context.getContentResolver().registerContentObserver(u,true,observer);registered=true;}catch(Exception ignored){}}failedImages.clear();refresh(true);main.removeCallbacks(periodic);main.removeCallbacks(reload);main.postDelayed(reload,2500);if(registered)main.postDelayed(periodic,1800000);}
  void stop(){if(sourceSync.active)android.util.Log.i("CastleShelf","Source polling paused");sourceSync.pause(SystemClock.uptimeMillis());main.removeCallbacks(sourcePoll);main.removeCallbacks(reload);main.removeCallbacks(periodic);if(registered){context.getContentResolver().unregisterContentObserver(observer);registered=false;}}
  void close(){closed=true;stop();worker.shutdownNow();artWorker.shutdownNow();main.removeCallbacksAndMessages(null);}
  String str(Cursor c,String name){int i=c.getColumnIndex(name);return i<0||c.isNull(i)?"":c.getString(i);}
  long number(Cursor c,String name){int i=c.getColumnIndex(name);return i<0||c.isNull(i)?0:c.getLong(i);}
  String label(String pkg){try{return context.getPackageManager().getApplicationLabel(context.getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception e){return pkg;}}
  List<Item> read(Uri uri,boolean watch,Map<Long,String> channels,Set<Long> historyChannels)throws Exception{ArrayList<Item> out=new ArrayList<>();String[] columns=watch?new String[]{"_id","title","package_name","intent_uri","poster_art_uri","last_playback_position_millis","duration_millis","last_engagement_time_utc_millis","watch_next_type","browsable"}:new String[]{"_id","title","package_name","intent_uri","poster_art_uri","last_playback_position_millis","duration_millis","channel_id","browsable"};HashSet<String> seen=new HashSet<>();HashMap<String,Integer> perApp=new HashMap<>();int scanned=0;try(Cursor c=context.getContentResolver().query(uri,columns,null,null,watch?"last_engagement_time_utc_millis DESC":"weight DESC")){while(c!=null&&c.moveToNext()&&out.size()<200&&scanned++<1500){if(number(c,"browsable")==0)continue;Item x=new Item();x.title=str(c,"title");x.pkg=str(c,"package_name");x.intent=str(c,"intent_uri");if(x.title.length()==0||x.pkg.length()==0||x.intent.length()==0)continue;try{context.getPackageManager().getApplicationInfo(x.pkg,0);}catch(Exception e){continue;}x.recent=!watch&&historyChannels.contains(number(c,"channel_id"));String bucket=x.pkg+(x.recent?":history":"");x.id=number(c,"_id");x.poster=str(c,"poster_art_uri");x.position=number(c,"last_playback_position_millis");x.duration=number(c,"duration_millis");x.engaged=number(c,"last_engagement_time_utc_millis");x.type=number(c,"watch_next_type");if(watch&&!TvCardPolicy.continuing(x.type,x.position,x.duration))continue;if(!seen.add(TvCardPolicy.rowKey(x.pkg,x.intent,x.recent)))continue;int count=perApp.containsKey(bucket)?perApp.get(bucket):0;if(!watch&&count>=20)continue;perApp.put(bucket,count+1);String channel=watch?null:channels.get(number(c,"channel_id"));x.source=label(x.pkg)+(channel==null?"":" · "+channel);out.add(x);}}if(watch)Collections.sort(out,new Comparator<Item>(){public int compare(Item a,Item b){boolean ar=a.position>0&&(a.duration<=0||a.position<a.duration),br=b.position>0&&(b.duration<=0||b.position<b.duration);if(ar!=br)return ar?-1:1;return Long.compare(b.engaged,a.engaged);}});if(!watch)Collections.sort(out,new Comparator<Item>(){public int compare(Item a,Item b){if(a.recent!=b.recent)return a.recent?-1:1;return Boolean.compare(LivePlayback.allowedPackage(b.pkg),LivePlayback.allowedPackage(a.pkg));}});return Collections.unmodifiableList(new ArrayList<Item>(out.subList(0,Math.min(60,out.size()))));}
  void refresh(boolean force){if(closed)return;if(loading){refreshAgain|=force;return;}denied=!allowed();if(denied){next=Collections.emptyList();picks=Collections.emptyList();changed.run();return;}long now=SystemClock.uptimeMillis();if(!force&&loaded&&now-lastLoad<15000)return;loading=true;worker.execute(new Runnable(){public void run(){List<Item> a=Collections.emptyList(),b=Collections.emptyList();boolean an=false,bn=false;HashMap<Long,String> channels=new HashMap<>();HashSet<Long> historyChannels=new HashSet<>();try(Cursor c=context.getContentResolver().query(CHANNEL,new String[]{"_id","display_name","package_name","internal_provider_id"},null,null,null)){while(c!=null&&c.moveToNext()){channels.put(c.getLong(0),c.getString(1));if(str(c,"package_name").contains("smarttube")&&"2".equals(str(c,"internal_provider_id")))historyChannels.add(c.getLong(0));}}catch(Exception ignored){}try{a=read(NEXT,true,channels,historyChannels);}catch(Exception e){an=true;android.util.Log.w("CastleShelf","WatchNext read failed: "+e.getClass().getSimpleName());}try{b=read(PREVIEW,false,channels,historyChannels);}catch(Exception e){bn=true;android.util.Log.w("CastleShelf","Preview read failed: "+e.getClass().getSimpleName());}final List<Item> aa=a,bb=b;final boolean ae=an,be=bn;main.post(new Runnable(){public void run(){if(closed)return;loading=false;loaded=true;failed=ae||be;lastLoad=SystemClock.uptimeMillis();rawNext=aa;rawPicks=bb;if(resetPending){for(Item i:aa)hidden.add(fingerprint(i));for(Item i:bb)hidden.add(fingerprint(i));persistHidden();if(!failed)resetPending=false;}ArrayList<Item> resume=new ArrayList<>(),recommendations=new ArrayList<>();HashSet<String> historyIntents=new HashSet<>();for(Item item:visible(bb)){if(item.recent){resume.add(item);historyIntents.add(item.pkg+item.intent);}else recommendations.add(item);}for(Item item:visible(aa))if(!historyIntents.contains(item.pkg+item.intent))resume.add(item);next=LivePlayback.merge(context,resume);picks=Collections.unmodifiableList(recommendations);if(!failed)sourceSync.observe(SystemClock.uptimeMillis(),publication());android.util.Log.i("CastleShelf","WatchNext="+next.size()+" rawNext="+rawNext.size()+" preview="+picks.size()+" hidden="+hidden.size()+" failedNext="+ae+" failedPreview="+be);changed.run();if(refreshAgain){refreshAgain=false;refresh(true);}}});}});}
  String status(){if(sourceSync.active)return syncMessage;if(!syncMessage.isEmpty())return syncMessage;return denied?"Нужен доступ к ТВ-спискам":loading&&!loaded?"Загрузка карточек Android TV…":failed?"Не удалось прочитать ТВ-списки":!hidden.isEmpty()&&next.isEmpty()&&picks.isEmpty()?"Старые карточки скрыты. Ждём новые данные приложений.":"Карточки публикуют установленные приложения";}
  Bitmap image(final Item item){if(item.poster.length()==0||closed)return null;Bitmap cached=images.get(item.poster);if(cached!=null)return cached;if(failedImages.contains(item.poster)||!pending.add(item.poster))return null;final int generation=artGeneration;artWorker.execute(new Runnable(){public void run(){Bitmap result=null;HttpURLConnection conn=null;try{Uri uri=Uri.parse(item.poster);InputStream in;if("https".equals(uri.getScheme())){conn=(HttpURLConnection)new URL(item.poster).openConnection();conn.setConnectTimeout(4000);conn.setReadTimeout(4000);conn.setInstanceFollowRedirects(false);if(conn.getResponseCode()!=200)throw new IOException();in=conn.getInputStream();}else if("content".equals(uri.getScheme())||"android.resource".equals(uri.getScheme()))in=context.getContentResolver().openInputStream(uri);else throw new IOException();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream stream=in){byte[] buf=new byte[4096];int n;while((n=stream.read(buf))!=-1){if(bytes.size()+n>2097152)throw new IOException();bytes.write(buf,0,n);}}byte[] data=bytes.toByteArray();BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,opt);if(opt.outWidth<=0||opt.outHeight<=0||opt.outWidth>20000||opt.outHeight>20000)throw new IOException();opt.inSampleSize=1;while(opt.outWidth/opt.inSampleSize>640||opt.outHeight/opt.inSampleSize>360)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;opt.inPreferredConfig=Bitmap.Config.RGB_565;result=BitmapFactory.decodeByteArray(data,0,data.length,opt);}catch(Exception ignored){}finally{if(conn!=null)conn.disconnect();}final Bitmap bmp=result;main.post(new Runnable(){public void run(){if(closed||generation!=artGeneration)return;pending.remove(item.poster);if(bmp==null)failedImages.add(item.poster);if(bmp!=null){images.put(item.poster,bmp);while(images.size()>6)images.remove(images.keySet().iterator().next());}changed.run();}});}});return null;}
}
